    private List<Task> tasksToday(){return tasksFor(Calendar.getInstance());}
    private List<Task> tasksFor(Calendar d){List<Task>a=new ArrayList<>();int day=d.get(Calendar.DAY_OF_WEEK);a.add(t("fajr",240,390,"الفجر والحلقة والدرس","الدين والمسجد",5,true,"mosque"));if(day==Calendar.SATURDAY)a.add(t("workoutA",390,420,"تمرين A — كتف وذراعان + جسم كامل","الصحة",18,true,"health"));if(day==Calendar.TUESDAY)a.add(t("workoutB",390,420,"تمرين B — أوتار وقبضة وسرعة","الصحة",18,true,"health"));a.add(t("english",420,480,englishTitle(day),"الإنجليزية",20,day!=Calendar.FRIDAY,"headphones"));a.add(t("sleep2",480,570,"النوم التكميلي","الصحة",5,true,"sleep"));a.add(t("medicine",570,660,medicineTitle(day),"الطب والقبول",28,day!=Calendar.FRIDAY,"medicine"));a.add(t("work",660,720,workTitle(day),"العمل والدخل",20,day!=Calendar.FRIDAY,"briefcase"));a.add(t("quran1",730,805,"القرآن — مراجعة جديدة: صفحتان","القرآن",16,true,"quran"));a.add(t("lunch",805,835,"الغداء","الانضباط",3,true,"meal"));a.add(t("leap1",835,865,"LeapAhead — الكتاب ١","المعرفة والقراءة",7,true,"book"));a.add(t("quran2",885,970,"القرآن — صفحتان + مراجعة قديمة","القرآن",18,true,"quran"));a.add(afternoon(day));a.add(t("maghrib",1080,1200,"المغرب والتحفيظ والعشاء","الدين والمسجد",5,true,"mosque"));a.add(t("dinner",1200,1230,"العشاء مع الأسرة","الأسرة",3,true,"home"));a.add(t("leap2",1230,1260,"LeapAhead — الكتاب ٢","المعرفة والقراءة",7,true,"book"));a.add(t("leap3",1260,1290,"LeapAhead — الكتاب ٣ (اختياري)","المعرفة والقراءة",7,false,"book"));a.add(t("close",1320,1340,"إغلاق اليوم وتجهيز الغد","الانضباط",6,true,"check"));a.add(t("sleep",1340,1350,"الاستعداد للنوم","الصحة",5,true,"sleep"));addCustom(a,d);return a;}
    private Task afternoon(int day){switch(day){case Calendar.SATURDAY:return t("family_talk",990,1020,"الأسرة + تدريب كلام قصير","الأسرة",8,true,"family");case Calendar.SUNDAY:return t("talk1",990,1020,"تدريب التواصل","التواصل",10,true,"talk");case Calendar.MONDAY:return t("family_friend",990,1020,"خدمة الأسرة + تفقد صديق","الأسرة",8,true,"family");case Calendar.TUESDAY:return t("talk2",990,1020,"تدريب الكلام والحزم","التواصل",10,true,"talk");case Calendar.WEDNESDAY:return t("medicine_review",990,1050,"مراجعة قبول إضافية — أحياء أو كيمياء","الطب والقبول",12,true,"medicine");case Calendar.THURSDAY:return t("khatera",990,1030,"خاطرة دينية + تدريب إلقاء","التواصل",10,true,"talk");default:return t("weekly_light",990,1040,"مراجعة أسبوعية خفيفة بلا إعادة بناء للخطة","الانضباط",8,false,"calendar");}}
    private void addCustom(List<Task>a,Calendar d){try{JSONArray arr=new JSONArray(prefs.getString("custom_tasks","[]"));for(int i=0;i<arr.length();i++){JSONObject o=arr.optJSONObject(i);if(o==null||!o.optBoolean("active",true))continue;int dy=o.optInt("day",0);if(dy!=0&&dy!=d.get(Calendar.DAY_OF_WEEK))continue;a.add(t(o.optString("id","custom_"+i),o.optInt("start",960),o.optInt("end",990),o.optString("title","مهمة مخصصة"),o.optString("domain","الانضباط"),o.optInt("points",10),o.optBoolean("required",false),"check"));}}catch(Exception ignored){}}
