    private String englishTitle(int d){switch(d){case Calendar.SATURDAY:return"الإنجليزية: Vocabulary + Reading Explorer";case Calendar.SUNDAY:return"الإنجليزية: Vocabulary + Tactics";case Calendar.MONDAY:return"الإنجليزية: Vocabulary + Reading Explorer";case Calendar.TUESDAY:return"الإنجليزية: Vocabulary + Tactics";case Calendar.WEDNESDAY:return"الإنجليزية: Vocabulary + Oxford Bookworms";case Calendar.THURSDAY:return"اختبار الإنجليزية الأسبوعي";default:return"استماع إنجليزي ممتع — يوم خفيف";}}
    private String medicineTitle(int d){switch(d){case Calendar.SATURDAY:return"القبول الطبي — أحياء";case Calendar.SUNDAY:return"القبول الطبي — كيمياء";case Calendar.MONDAY:return"القبول الطبي — أحياء + أسئلة";case Calendar.TUESDAY:return"القبول الطبي — كيمياء + مسائل";case Calendar.WEDNESDAY:return"القبول الطبي — إنجليزي علمي + مراجعة";case Calendar.THURSDAY:return"اختبار قبول مصغر";default:return"مراجعة خفيفة لما سبق";}}
    private String workTitle(int d){switch(d){case Calendar.SATURDAY:case Calendar.SUNDAY:return"العمل: تطوير المشروع الحالي";case Calendar.MONDAY:case Calendar.TUESDAY:return"العمل: الوصول للسوق";case Calendar.WEDNESDAY:return"العمل: دخل مباشر";case Calendar.THURSDAY:return"العمل: مراجعة الأرقام";default:return"مراجعة مالية خفيفة";}}
    private List<Task> homeTasks(){List<Task>all=tasksToday(),out=new ArrayList<>();int now=Calendar.getInstance().get(Calendar.HOUR_OF_DAY)*60+Calendar.getInstance().get(Calendar.MINUTE);for(Task t:all){if(t.id.equals("sleep2")||t.id.equals("lunch")||t.id.equals("dinner"))continue;if(!done(t)&&t.end>=now-30)out.add(t);if(out.size()>=5)break;}if(out.size()<5)for(Task t:all){if(out.contains(t)||t.id.equals("sleep2")||t.id.equals("lunch")||t.id.equals("dinner"))continue;out.add(t);if(out.size()>=5)break;}return out;}
    private boolean matches(Task t){if("الكل".equals(taskFilter))return true;if("قرآن".equals(taskFilter))return t.domain.equals("القرآن");if("طب".equals(taskFilter))return t.domain.equals("الطب والقبول");if("إنجليزية".equals(taskFilter))return t.domain.equals("الإنجليزية");if("عمل".equals(taskFilter))return t.domain.equals("العمل والدخل");if("صحة".equals(taskFilter))return t.domain.equals("الصحة");if("أسرة".equals(taskFilter))return t.domain.equals("الأسرة");if("LeapAhead".equals(taskFilter))return t.id.startsWith("leap");return true;}
    private boolean done(Task t){return prefs.getBoolean("reward_done_"+todayKey+"_"+t.id,false);}private boolean doneOn(Task t,Calendar d){return prefs.getBoolean("reward_done_"+dateKey(d)+"_"+t.id,false);}
    private void setDone(Task t,boolean val){boolean old=done(t);if(old==val)return;int delta=val?t.points:-t.points;String dk="reward_day_points_"+todayKey,dom="reward_domain_"+t.domain;prefs.edit().putBoolean("reward_done_"+todayKey+"_"+t.id,val).putInt(dk,Math.max(0,prefs.getInt(dk,0)+delta)).putInt(dom,Math.max(0,prefs.getInt(dom,0)+delta)).apply();syncCredits();Toast.makeText(this,val?"+"+t.points+" نقطة":"تم التراجع",Toast.LENGTH_SHORT).show();}
    private boolean coreDone(String id){for(Task t:tasksToday())if(t.id.equals(id)||("quran".equals(id)&&t.id.startsWith("quran")))if(done(t))return true;return false;}private int coreDoneToday(){int n=0;if(coreDone("quran"))n++;if(coreDone("medicine"))n++;if(coreDone("english"))n++;if(coreDone("work"))n++;if(coreDone("close"))n++;return n;}
    private int countDoneToday(){int n=0;for(Task t:tasksToday())if(done(t))n++;return n;}private int requiredCountToday(){int n=0;for(Task t:tasksToday())if(t.required)n++;return n;}private int requiredDoneToday(){int n=0;for(Task t:tasksToday())if(t.required&&done(t))n++;return n;}private int overdueCount(){int now=Calendar.getInstance().get(Calendar.HOUR_OF_DAY)*60+Calendar.getInstance().get(Calendar.MINUTE),n=0;for(Task t:tasksToday())if(!done(t)&&t.end<now)n++;return n;}
    private int dayPoints(Calendar c){return prefs.getInt("reward_day_points_"+dateKey(c),0);}private int dayTarget(Calendar c){int n=0;for(Task t:tasksFor(c))if(t.required)n+=t.points;return Math.max(1,n);}private int dayRate(Calendar c){return pct(dayPoints(c),dayTarget(c));}
    private int weekRate(){return weekRateAt(0);}private int weekRateAt(int back){Calendar st=saturdayStart(Calendar.getInstance());st.add(Calendar.DAY_OF_MONTH,-7*back);Calendar en=(Calendar)st.clone();en.add(Calendar.DAY_OF_MONTH,6);Calendar now=Calendar.getInstance();if(en.after(now))en=now;int p=0,t=0;while(!st.after(en)){p+=dayPoints(st);t+=dayTarget(st);st.add(Calendar.DAY_OF_MONTH,1);}return pct(p,t);}private int monthRate(){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.DAY_OF_MONTH,1);int p=0,t=0;while(!c.after(now)){p+=dayPoints(c);t+=dayTarget(c);c.add(Calendar.DAY_OF_MONTH,1);}return pct(p,t);}private int yearRate(){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.MONTH,Calendar.JANUARY);c.set(Calendar.DAY_OF_MONTH,1);int p=0,t=0;while(!c.after(now)){p+=dayPoints(c);t+=dayTarget(c);c.add(Calendar.DAY_OF_MONTH,1);}return pct(p,t);}
    private int monthCompleted(){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.DAY_OF_MONTH,1);int n=0;while(!c.after(now)){for(Task t:tasksFor(c))if(doneOn(t,c))n++;c.add(Calendar.DAY_OF_MONTH,1);}return n;}private int monthTaskCount(){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.DAY_OF_MONTH,1);int n=0;while(!c.after(now)){n+=tasksFor(c).size();c.add(Calendar.DAY_OF_MONTH,1);}return n;}private int monthDoneId(String part){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.DAY_OF_MONTH,1);int n=0;while(!c.after(now)){for(Task t:tasksFor(c))if(t.id.contains(part)&&doneOn(t,c))n++;c.add(Calendar.DAY_OF_MONTH,1);}return n;}private int quranPagesThisMonth(){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.DAY_OF_MONTH,1);int n=0;while(!c.after(now)){for(Task t:tasksFor(c))if(t.id.startsWith("quran")&&doneOn(t,c))n+=2;c.add(Calendar.DAY_OF_MONTH,1);}return n;}
    private int focusMinutes(){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.DAY_OF_MONTH,1);int sum=0;while(!c.after(now)){String key=dateKey(c);for(Task t:tasksFor(c))if(prefs.getBoolean("reward_done_"+key+"_"+t.id,false)&&(t.domain.equals("الطب والقبول")||t.domain.equals("الإنجليزية")||t.domain.equals("العمل والدخل")||t.domain.equals("القرآن")||t.domain.equals("المعرفة والقراءة")))sum+=Math.max(0,t.end-t.start);c.add(Calendar.DAY_OF_MONTH,1);}return sum;}
    private int streak(){Calendar c=Calendar.getInstance();if(dayRate(c)<80)c.add(Calendar.DAY_OF_MONTH,-1);int n=0;for(int i=0;i<365;i++){if(dayRate(c)>=80){n++;c.add(Calendar.DAY_OF_MONTH,-1);}else break;}return n;}private int strongThisWeek(){Calendar c=saturdayStart(Calendar.getInstance()),now=Calendar.getInstance();int n=0;while(!c.after(now)){if(dayRate(c)>=80)n++;c.add(Calendar.DAY_OF_MONTH,1);}return n;}private int countDoneIds(String contains){int n=0;for(Map.Entry<String,?>e:prefs.getAll().entrySet())if(e.getKey().startsWith("reward_done_")&&e.getKey().contains(contains)&&Boolean.TRUE.equals(e.getValue()))n++;return n;}
    private int weekDomainRate(String d){Calendar c=saturdayStart(Calendar.getInstance()),now=Calendar.getInstance();int e=0,t=0;while(!c.after(now)){for(Task x:tasksFor(c)){if(!x.domain.equals(d))continue;if(x.required)t+=x.points;if(doneOn(x,c))e+=x.points;}c.add(Calendar.DAY_OF_MONTH,1);}return pct(e,Math.max(1,t));}
    private int domainPoints(String d){return prefs.getInt("reward_domain_"+d,0);}private int totalPoints(){int n=0;for(String d:domainColors.keySet())n+=domainPoints(d);return n;}private int credits(){return prefs.getInt("reward_credits",0);}
    private void syncCredits(){SharedPreferences.Editor e=prefs.edit();int add=0;String dk=todayKey;if(coreDoneToday()>=4&&!prefs.getBoolean("credit_core4_"+dk,false)){add+=6;e.putBoolean("credit_core4_"+dk,true);}if(coreDoneToday()==5&&!prefs.getBoolean("credit_core5_"+dk,false)){add+=4;e.putBoolean("credit_core5_"+dk,true);}Calendar now=Calendar.getInstance();String wk=now.get(Calendar.YEAR)+"_"+now.get(Calendar.WEEK_OF_YEAR);if(strongThisWeek()>=5&&!prefs.getBoolean("credit_week5_"+wk,false)){add+=20;e.putBoolean("credit_week5_"+wk,true);}add+=awardOnce(e,"credit_medicine15",countDoneIds("medicine")>=15,20);add+=awardOnce(e,"credit_quran20",countDoneIds("quran")>=20,20);add+=awardOnce(e,"credit_streak7",streak()>=7,30);if(add>0)e.putInt("reward_credits",credits()+add);e.apply();}private int awardOnce(SharedPreferences.Editor e,String key,boolean ok,int amount){if(ok&&!prefs.getBoolean(key,false)){e.putBoolean(key,true);return amount;}return 0;}
    private int levelFor(int p){if(p>=8000)return 6;if(p>=5000)return 5;if(p>=3000)return 4;if(p>=1500)return 3;if(p>=600)return 2;return 1;}private int levelBase(int l){switch(l){case 2:return 600;case 3:return 1500;case 4:return 3000;case 5:return 5000;case 6:return 8000;default:return 0;}}private int levelNext(int l){switch(l){case 1:return 600;case 2:return 1500;case 3:return 3000;case 4:return 5000;case 5:return 8000;default:return 10000;}}private String levelName(int l){switch(l){case 2:return"منتظم";case 3:return"متقدم";case 4:return"راسخ";case 5:return"متقن";case 6:return"متمكن";default:return"البداية";}}private String levelMessage(int l){switch(l){case 1:return"ثبت الأساس قبل زيادة الحمل.";case 2:return"الاستمرار أهم من الكثرة.";case 3:return"تقدمك صار قابلًا للقياس.";case 4:return"العادة بدأت تصبح راسخة.";case 5:return"جودة التنفيذ الآن أهم من العدد.";default:return"حافظ على الاتزان ولا تضف أهدافًا لمجرد النقاط.";}}
    private String rankFor(int p){if(p>=1200)return"متمكن";if(p>=650)return"ذهبي";if(p>=300)return"فضي";return"برونزي";}private int rankBase(int p){if(p>=1200)return 1200;if(p>=650)return 650;if(p>=300)return 300;return 0;}private int rankNext(int p){if(p>=1200)return 1800;if(p>=650)return 1200;if(p>=300)return 650;return 300;}
    private String topBlocker(){String x=prefs.getString("weekly_blocker","");if(x==null||x.trim().isEmpty())x=prefs.getString("last_blocker","");return x==null||x.trim().isEmpty()?"لم يُسجّل بعد":x;}

    private LinearLayout root(ScrollView s){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);r.setPadding(dp(13),dp(3),dp(13),dp(8));s.addView(r,new ScrollView.LayoutParams(-1,-2));return r;}private ScrollView scroll(){ScrollView s=new ScrollView(this);s.setFillViewport(true);s.setClipToPadding(false);s.setBackgroundColor(BG);return s;}private LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setBackground(round(CARD,15,BORDER));c.setElevation(dp(.6f));return c;}private void add(LinearLayout r,View v,int top){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(top),0,0);r.addView(v,p);}private void gap(LinearLayout r,int v){View x=new View(this);r.addView(x,new LinearLayout.LayoutParams(1,dp(v)));}private void divider(LinearLayout p){View v=new View(this);v.setBackgroundColor(BORDER);p.addView(v,new LinearLayout.LayoutParams(-1,dp(1)));}
    private TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);t.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);t.setTypeface(Typeface.create("sans-serif",bold?Typeface.BOLD:Typeface.NORMAL));t.setIncludeFontPadding(false);return t;}private TextView center(String s,int size,int color,boolean bold){TextView t=text(s,size,color,bold);t.setGravity(Gravity.CENTER);return t;}private Button primaryButton(String s){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setTextSize(12);b.setAllCaps(false);b.setTypeface(Typeface.DEFAULT_BOLD);b.setBackground(round(GREEN,22));b.setElevation(dp(1));return b;}
    private View progress(int value,int max,int color,int height){FrameLayout f=new FrameLayout(this);f.setBackground(round(TRACK,height));int pc=max<=0?0:Math.max(0,Math.min(100,Math.round(value*100f/max)));View fill=new View(this);fill.setBackground(round(color,height));f.addView(fill,new FrameLayout.LayoutParams(0,dp(height)));f.post(()->{ViewGroup.LayoutParams p=fill.getLayoutParams();p.width=Math.round(f.getWidth()*pc/100f);p.height=dp(height);fill.setLayoutParams(p);});f.setMinimumHeight(dp(height));return f;}
    private GradientDrawable round(int c,int r){return round(c,r,c);}private GradientDrawable round(int c,int r,int stroke){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));if(stroke!=c)g.setStroke(dp(1),stroke);return g;}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}private int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}private int pct(int a,int b){return b<=0?0:Math.max(0,Math.min(100,Math.round(a*100f/b)));}
    private String dateKey(Calendar c){return new SimpleDateFormat("yyyyMMdd",Locale.US).format(c.getTime());}private Calendar saturdayStart(Calendar now){Calendar c=(Calendar)now.clone();while(c.get(Calendar.DAY_OF_WEEK)!=Calendar.SATURDAY)c.add(Calendar.DAY_OF_MONTH,-1);c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);return c;}private String time(int min){int h=(min/60)%24,m=min%60;String suf=h>=12?"م":"ص";int hh=h%12;if(hh==0)hh=12;return ar(hh)+":"+(m<10?"٠":"")+ar(m)+" "+suf;}private String formatMinutes(int min){if(min<60)return ar(min)+" د";int h=min/60,m=min%60;return ar(h)+"س"+(m>0?" "+ar(m)+"د":"");}
    private String shortDomain(String d){if(d==null)return"—";if(d.equals("الطب والقبول"))return"الطب";if(d.equals("العمل والدخل"))return"العمل";if(d.equals("المعرفة والقراءة"))return"القراءة";if(d.equals("الدين والمسجد"))return"المسجد";return d;}private String iconForDomain(String d){if(d.equals("القرآن"))return"quran";if(d.equals("الطب والقبول"))return"medicine";if(d.equals("الإنجليزية"))return"headphones";if(d.equals("العمل والدخل"))return"briefcase";if(d.equals("الصحة"))return"heart";if(d.equals("المعرفة والقراءة"))return"book";if(d.equals("التواصل"))return"talk";if(d.equals("الأسرة"))return"family";if(d.equals("الدين والمسجد"))return"mosque";return"star";}private String ar(int n){String s=String.valueOf(n),e="0123456789",a="٠١٢٣٤٥٦٧٨٩";for(int i=0;i<10;i++)s=s.replace(e.charAt(i),a.charAt(i));return s;}

