    private class TrendView extends View{private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);TrendView(Activity a){super(a);}@Override protected void onDraw(Canvas c){float w=getWidth(),h=getHeight(),l=w*.07f,r=w*.96f,t=h*.12f,b=h*.78f;p.setColor(Color.rgb(232,236,239));p.setStrokeWidth(dp(1));for(int i=0;i<=4;i++){float y=t+(b-t)*i/4f;c.drawLine(l,y,r,y,p);}Path path=new Path();int n=14;for(int i=0;i<n;i++){Calendar d=Calendar.getInstance();d.add(Calendar.DAY_OF_MONTH,-(n-1-i)*2);float x=l+(r-l)*i/(n-1f),y=b-(b-t)*dayRate(d)/100f;if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(2));p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);p.setColor(GREEN);c.drawPath(path,p);p.setStyle(Paint.Style.FILL);for(int i=0;i<n;i++){Calendar d=Calendar.getInstance();d.add(Calendar.DAY_OF_MONTH,-(n-1-i)*2);float x=l+(r-l)*i/(n-1f),y=b-(b-t)*dayRate(d)/100f;c.drawCircle(x,y,dp(2.2f),p);}p.setTextAlign(Paint.Align.CENTER);p.setTextSize(dp(7));p.setColor(MUTED);c.drawText("بداية الشهر",l,b+dp(15),p);c.drawText("اليوم",r,b+dp(15),p);}}
