    private static void drawStar(Canvas c,Paint p,float cx,float cy,float r,int col){Path x=new Path();for(int i=0;i<10;i++){double a=-Math.PI/2+i*Math.PI/5;float rr=i%2==0?r:r*.45f,px=cx+(float)Math.cos(a)*rr,py=cy+(float)Math.sin(a)*rr;if(i==0)x.moveTo(px,py);else x.lineTo(px,py);}x.close();p.setStyle(Paint.Style.FILL);p.setColor(col);c.drawPath(x,p);}private static int lighten(int c,float a){return Color.rgb((int)(Color.red(c)+(255-Color.red(c))*a),(int)(Color.green(c)+(255-Color.green(c))*a),(int)(Color.blue(c)+(255-Color.blue(c))*a));}private static int darken(int c,float a){return Color.rgb((int)(Color.red(c)*(1-a)),(int)(Color.green(c)*(1-a)),(int)(Color.blue(c)*(1-a)));}private static String toArabic(int n){String s=String.valueOf(n),e="0123456789",a="٠١٢٣٤٥٦٧٨٩";for(int i=0;i<10;i++)s=s.replace(e.charAt(i),a.charAt(i));return s;}
